fn find_minimum_total_distance(x1: i8, x2: i8, x3: i8) -> i8 {
    // The sum of absolute distances to a meeting point is minimized
    // when the meeting point is the median of the three positions.
    let mut positions = [x1, x2, x3];
    positions.sort_unstable();
    let median = positions[1];

    (x1 - median).abs() + (x2 - median).abs() + (x3 - median).abs()
}

